              <label class="radio-option" for="notification-push">
                <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                <span>Push Notifications</span>
              </label>
            </div>

            <p id="notification-error" class="error"></p>
          </fieldset>
        </div>

        <button type="submit">Save preference</button>
        <p id="form-status" class="status" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const radios = Array.from(document.querySelectorAll('input[name="notificationPreference"]'));
    const error = document.querySelector("#notification-error");
    const status = document.querySelector("#form-status");

    function setInvalidState(isInvalid) {
      radios.forEach((radio) => {
        radio.setAttribute("aria-invalid", String(isInvalid));
      });
    }

    function clearMessages() {
      error.textContent = "";
      status.textContent = "";
      setInvalidState(false);
    }

    radios.forEach((radio) => {
      radio.addEventListener("change", clearMessages);
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selected = radios.find((radio) => radio.checked);

      if (!selected) {
        error.textContent = "Error: Choose Email, SMS, or Push Notifications.";
        status.textContent = "";
        setInvalidState(true);
        radios[0].focus();
        return;
      }

