 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="card" aria-labelledby="page-title">
       <h1 id="page-title">Notification preferences</h1>
       <p class="intro">Tell us the best way to reach you with important updates.</p>

       <form id="notification-form" novalidate>
         <p class="required-note"><span aria-hidden="true">*</span> indicates a required question.</p>

         <div class="form-field">
           <fieldset id="notification-fieldset" aria-describedby="notification-help notification-error">
             <legend>
               How do you prefer to receive notifications?
               <span class="required-marker" aria-hidden="true">*</span>
             </legend>
             <p id="notification-help" class="field-help">Choose one notification method.</p>

             <div class="radio-options">
               <label class="radio-option" for="notification-email">
                 <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                 <span>Email</span>
               </label>

               <label class="radio-option" for="notification-sms">
                 <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                 <span>SMS</span>
               </label>

               <label class="radio-option" for="notification-push">
                 <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                 <span>Push Notifications</span>
               </label>
             </div>

             <p id="notification-error" class="error"></p>
           </fieldset>
         </div>

         <button type="submit">Save preference</button>
         <p id="form-status" class="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#notification-form");
     const radios = Array.from(document.querySelectorAll('input[name="notificationPreference"]'));
     const error = document.querySelector("#notification-error");
     const status = document.querySelector("#form-status");

     function setInvalidState(isInvalid) {
       radios.forEach((radio) => {
         radio.setAttribute("aria-invalid", String(isInvalid));
       });
     }

     function clearMessages() {
       error.textContent = "";
       status.textContent = "";
       setInvalidState(false);
     }

     radios.forEach((radio) => {
       radio.addEventListener("change", clearMessages);
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selected = radios.find((radio) => radio.checked);

       if (!selected) {
         error.textContent = "Error: Choose Email, SMS, or Push Notifications.";
         status.textContent = "";
         setInvalidState(true);
         radios[0].focus();
         return;
       }

       clearMessages();
       status.textContent = `Preference saved: ${selected.value}.`;
     });
   </script>
 </body>
